#include <stdio.h>

void timMinMax(int a[], int n, int *mn, int *mx) {
    *mn = a[0];
    *mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < *mn) *mn = a[i];
        if (a[i] > *mx) *mx = a[i];
    }
}

void hoanDoi(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int main() {
    int n;
    int a[105];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int v;
        scanf("%d", &v);
        a[i] = v;
    }
    int mn, mx;
    timMinMax(a, n, &mn, &mx);
    printf("%d %d\n", mn, mx);
    int vmin = 0, vmax = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] == mn) { vmin = i; break; }
    }
    for (int i = 0; i < n; i++) {
        if (a[i] == mx) { vmax = i; break; }
    }
    hoanDoi(&a[vmin], &a[vmax]);
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
    return 0;
}

lessons.theory:
Một học sinh có nhiều thông tin: mã số, điểm Toán, Văn, Anh… Trong C chuẩn, ta gom chúng thành một **kiểu cấu trúc** bằng từ khóa `struct`:

```c
struct HocSinh {
    int ma;
    int toan, van, anh;
};

struct HocSinh ds[50];          // mảng 50 học sinh
ds[0].ma = 101;                 // truy cập thành phần bằng dấu chấm
```

`struct` giúp mã nguồn rõ nghĩa: mọi dữ liệu của một học sinh đi cùng nhau.

> **Lưu ý về trình chạy trên trình duyệt:** trình thông dịch C dùng trong V-Code Edu hiện **chưa hỗ trợ `struct`**. Vì vậy ở bài này ta dùng kỹ thuật tương đương là **mảng song song** — mỗi thuộc tính là một mảng, và phần tử thứ `i` của mọi mảng cùng mô tả học sinh thứ `i`. Khi lập trình với trình biên dịch thật (GCC, Code::Blocks, Dev-C++), em nên dùng `struct`.

```c
int ma[50], toan[50], van[50], anh[50];
for (int i = 0; i < n; i++) {
    int m, t, v, a;
    scanf("%d %d %d %d", &m, &t, &v, &a);
    ma[i] = m; toan[i] = t; van[i] = v; anh[i] = a;
}
```

Để tìm **thủ khoa** (tổng điểm cao nhất, nếu bằng nhau lấy người nhập trước), lưu **chỉ số** của người tốt nhất thay vì lưu điểm — từ chỉ số ta lấy được mọi thông tin khác:

```c
int best = 0;
for (int i = 1; i < n; i++) {
    if (tong(i) > tong(best)) best = i;   // dấu > (không phải >=) giữ người đến trước
}
```

Điểm trung bình phải tính bằng số thực: `tong / 3.0`. Nếu viết `tong / 3` em sẽ nhận phép chia nguyên và mất phần thập phân.

