#include <stdio.h>

int main() {
    int n;
    int ma[55], toan[55], van[55], anh[55];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int m, t, v, a;
        scanf("%d %d %d %d", &m, &t, &v, &a);
        ma[i] = m; toan[i] = t; van[i] = v; anh[i] = a;
    }
    int best = 0, dat = 0;
    for (int i = 0; i < n; i++) {
        int tong = toan[i] + van[i] + anh[i];
        if (tong > toan[best] + van[best] + anh[best]) best = i;
        if (tong / 3.0 >= 5.0) dat++;
    }
    int tb = toan[best] + van[best] + anh[best];
    printf("Thu khoa: %d\n", ma[best]);
    printf("Diem TB: %.2f\n", tb / 3.0);
    printf("Dat: %d\n", dat);
    return 0;
}
